package com.arenashowdown.core.persistence;

import com.arenashowdown.api.model.*;
import java.sql.*;
import java.time.*;
import java.util.*;

public final class JdbcOrchestrationRepository implements OrchestrationRepository {
    private final Database database;
    public JdbcOrchestrationRepository(Database database) { this.database = database; }

    @Override public void createChampionship(ChampionshipDetails d, String actor) throws SQLException {
        try (Connection c=database.connection()) { c.setAutoCommit(false); try {
            try(PreparedStatement p=c.prepareStatement("INSERT INTO championships(id,name,state,created_at) VALUES(?,?,?,?)")){p.setString(1,d.id());p.setString(2,d.name());p.setString(3,d.state().name());p.setString(4,d.createdAt().toString());p.executeUpdate();}
            try(PreparedStatement p=c.prepareStatement("INSERT INTO championship_settings(championship_id,mode,minigame_sequence,current_round,tie_breaker) VALUES(?,?,?,?,?)")){p.setString(1,d.id());p.setString(2,d.mode().name());p.setString(3,String.join(",",d.minigames()));p.setInt(4,d.currentRound());p.setString(5,d.tieBreaker().name());p.executeUpdate();}
            audit(c,d.id(),actor,"CHAMPIONSHIP_CREATED",d.name()); c.commit();
        } catch(SQLException e){c.rollback();throw e;} finally{c.setAutoCommit(true);} }
    }

    @Override public Optional<ChampionshipDetails> championshipDetails(String id) throws SQLException {
        String sql="SELECT c.id,c.name,c.state,c.created_at,s.mode,s.minigame_sequence,s.current_round,s.tie_breaker,s.champion_id,s.completed_at FROM championships c JOIN championship_settings s ON s.championship_id=c.id WHERE c.id=?";
        try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(details(r)):Optional.empty();}}
    }

    @Override public void updateChampionshipProgress(String id,int round,String championId,Instant completedAt)throws SQLException{
        try(Connection c=database.connection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE championship_settings SET current_round=?,champion_id=?,completed_at=? WHERE championship_id=?")){p.setInt(1,round);p.setString(2,championId);p.setString(3,completedAt==null?null:completedAt.toString());p.setString(4,id);p.executeUpdate();}if(completedAt!=null){try(PreparedStatement p=c.prepareStatement("INSERT OR REPLACE INTO championship_history(championship_id,champion_id,mode,rounds,completed_at) SELECT championship_id,?,mode,?,? FROM championship_settings WHERE championship_id=?")){p.setString(1,championId);p.setInt(2,round);p.setString(3,completedAt.toString());p.setString(4,id);p.executeUpdate();}}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    @Override public void createTeam(Team t,String actor)throws SQLException{try(Connection c=database.connection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("INSERT INTO teams(championship_id,id,name,created_at) VALUES(?,?,?,?)")){p.setString(1,t.championshipId());p.setString(2,t.id());p.setString(3,t.name());p.setString(4,t.createdAt().toString());p.executeUpdate();}audit(c,t.championshipId(),actor,"TEAM_CREATED",t.id());c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    @Override public List<Team> teams(String id)throws SQLException{List<Team>x=new ArrayList<>();try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("SELECT championship_id,id,name,created_at FROM teams WHERE championship_id=? ORDER BY name")){p.setString(1,id);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new Team(r.getString(1),r.getString(2),r.getString(3),Instant.parse(r.getString(4))));}}return x;}
    @Override public void assignTeam(String championshipId,UUID playerId,String teamId,String actor)throws SQLException{try(Connection c=database.connection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE participants SET team_id=? WHERE championship_id=? AND player_id=? AND EXISTS(SELECT 1 FROM teams WHERE championship_id=? AND id=?)")){p.setString(1,teamId);p.setString(2,championshipId);p.setString(3,playerId.toString());p.setString(4,championshipId);p.setString(5,teamId);if(p.executeUpdate()!=1)throw new SQLException("Participante ou equipe não encontrado");}audit(c,championshipId,actor,"TEAM_ASSIGNED",playerId+" -> "+teamId);c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}

    @Override public void createMatch(ArenaMatch m,String actor)throws SQLException{try(Connection c=database.connection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("INSERT INTO matches(id,championship_id,round_number,minigame,arena,state,reconnect_allowed,scheduled_at) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,m.id());p.setString(2,m.championshipId());p.setInt(3,m.round());p.setString(4,m.minigame());p.setString(5,m.arena());p.setString(6,m.state().name());p.setInt(7,m.reconnectAllowed()?1:0);p.setString(8,m.scheduledAt()==null?null:m.scheduledAt().toString());p.executeUpdate();}for(UUID player:m.participants()){try(PreparedStatement p=c.prepareStatement("INSERT INTO match_participants(match_id,player_id,team_id,status) SELECT ?,player_id,team_id,? FROM participants WHERE championship_id=? AND player_id=?")){p.setString(1,m.id());p.setString(2,ParticipantStatus.REGISTERED.name());p.setString(3,m.championshipId());p.setString(4,player.toString());if(p.executeUpdate()!=1)throw new SQLException("Participante não inscrito: "+player);}}audit(c,m.championshipId(),actor,"MATCH_CREATED",m.id());c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    @Override public Optional<ArenaMatch> match(String id)throws SQLException{return matchesBy("WHERE m.id=?",id).stream().findFirst();}
    @Override public List<ArenaMatch> matches(String id)throws SQLException{return matchesBy("WHERE m.championship_id=? ORDER BY m.round_number",id);}
    @Override public Optional<ArenaMatch> activeMatch(UUID playerId)throws SQLException{String sql="SELECT m.id FROM matches m JOIN match_participants p ON p.match_id=m.id WHERE p.player_id=? AND m.state IN ('PREPARING','COUNTDOWN','RUNNING') ORDER BY m.round_number DESC LIMIT 1";try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,playerId.toString());try(ResultSet r=p.executeQuery()){return r.next()?match(r.getString(1)):Optional.empty();}}}
    private List<ArenaMatch> matchesBy(String where,String value)throws SQLException{String sql="SELECT m.* FROM matches m "+where;List<ArenaMatch>x=new ArrayList<>();try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,value);try(ResultSet r=p.executeQuery()){while(r.next())x.add(readMatch(c,r));}}return x;}
    private ArenaMatch readMatch(Connection c,ResultSet r)throws SQLException{List<UUID>players=new ArrayList<>();Set<String>teams=new LinkedHashSet<>();try(PreparedStatement p=c.prepareStatement("SELECT player_id,team_id FROM match_participants WHERE match_id=?")){p.setString(1,r.getString("id"));try(ResultSet q=p.executeQuery()){while(q.next()){players.add(UUID.fromString(q.getString(1)));if(q.getString(2)!=null)teams.add(q.getString(2));}}}Instant start=parse(r.getString("started_at"));Number duration=(Number)r.getObject("duration_ms");return new ArenaMatch(r.getString("id"),r.getString("championship_id"),r.getInt("round_number"),r.getString("minigame"),r.getString("arena"),MatchState.valueOf(r.getString("state")),players,List.copyOf(teams),r.getInt("reconnect_allowed")==1,parse(r.getString("scheduled_at")),start,duration==null?null:Duration.ofMillis(duration.longValue()),r.getString("result_id"));}
    @Override public boolean updateMatchState(String id,MatchState expected,MatchState next,Instant startedAt,String reason)throws SQLException{try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("UPDATE matches SET state=?,started_at=COALESCE(started_at,?),cancellation_reason=? WHERE id=? AND state=?")){p.setString(1,next.name());p.setString(2,startedAt==null?null:startedAt.toString());p.setString(3,reason);p.setString(4,id);p.setString(5,expected.name());return p.executeUpdate()==1;}}
    @Override public void updateParticipantStatus(String matchId,UUID playerId,ParticipantStatus status,Instant disconnectedAt)throws SQLException{try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("UPDATE match_participants SET status=?,disconnected_at=? WHERE match_id=? AND player_id=?")){p.setString(1,status.name());p.setString(2,disconnectedAt==null?null:disconnectedAt.toString());p.setString(3,matchId);p.setString(4,playerId.toString());if(p.executeUpdate()!=1)throw new SQLException("Participante não pertence à partida");}}
    @Override public Optional<ParticipantStatus> participantStatus(String matchId,UUID playerId)throws SQLException{try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("SELECT status FROM match_participants WHERE match_id=? AND player_id=?")){p.setString(1,matchId);p.setString(2,playerId.toString());try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(ParticipantStatus.valueOf(r.getString(1))):Optional.empty();}}}

    @Override public boolean finalizeMatch(MatchResult result,String actor)throws SQLException{try(Connection c=database.connection()){c.setAutoCommit(false);try{String champ;int round;Instant started;try(PreparedStatement p=c.prepareStatement("SELECT championship_id,round_number,started_at FROM matches WHERE id=? AND state='RUNNING'")){p.setString(1,result.matchId());try(ResultSet r=p.executeQuery()){if(!r.next()){c.rollback();return false;}champ=r.getString(1);round=r.getInt(2);started=parse(r.getString(3));}}try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO match_results(id,match_id,is_tie,recorded_at) VALUES(?,?,?,?)")){p.setString(1,result.id());p.setString(2,result.matchId());p.setInt(3,result.tie()?1:0);p.setString(4,result.recordedAt().toString());if(p.executeUpdate()!=1){c.rollback();return false;}}for(ResultEntry e:result.entries()){try(PreparedStatement p=c.prepareStatement("INSERT INTO result_entries(result_id,player_id,team_id,position,points,winner) VALUES(?,?,?,?,?,?)")){p.setString(1,result.id());p.setString(2,e.playerId().toString());p.setString(3,e.teamId());p.setInt(4,e.position());p.setInt(5,e.points());p.setInt(6,e.winner()?1:0);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO score_events(event_id,championship_id,player_id,points,source,created_at) VALUES(?,?,?,?,?,?)")){p.setString(1,"match:"+result.matchId()+":player:"+e.playerId());p.setString(2,champ);p.setString(3,e.playerId().toString());p.setInt(4,e.points());p.setString(5,"match:"+result.matchId());p.setString(6,result.recordedAt().toString());p.executeUpdate();}if(e.teamId()!=null){try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO team_score_events(event_id,championship_id,team_id,points,source,created_at) VALUES(?,?,?,?,?,?)")){p.setString(1,"match:"+result.matchId()+":team:"+e.teamId()+":player:"+e.playerId());p.setString(2,champ);p.setString(3,e.teamId());p.setInt(4,e.points());p.setString(5,"match:"+result.matchId());p.setString(6,result.recordedAt().toString());p.executeUpdate();}}}long duration=started==null?0:Duration.between(started,result.recordedAt()).toMillis();try(PreparedStatement p=c.prepareStatement("UPDATE matches SET state='FINISHED',result_id=?,duration_ms=? WHERE id=? AND state='RUNNING'")){p.setString(1,result.id());p.setLong(2,Math.max(0,duration));p.setString(3,result.matchId());if(p.executeUpdate()!=1){c.rollback();return false;}}try(PreparedStatement p=c.prepareStatement("UPDATE championship_settings SET current_round=MAX(current_round,?) WHERE championship_id=?")){p.setInt(1,round);p.setString(2,champ);p.executeUpdate();}audit(c,champ,actor,"MATCH_FINISHED",result.matchId()+" result="+result.id());c.commit();return true;}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}

    @Override public List<TeamRankingEntry> teamRanking(String id,int limit)throws SQLException{String sql="SELECT t.id,t.name,COALESCE(SUM(s.points),0),COALESCE((SELECT COUNT(DISTINCT re.result_id) FROM result_entries re JOIN match_results mr ON mr.id=re.result_id JOIN matches m ON m.id=mr.match_id WHERE m.championship_id=t.championship_id AND re.team_id=t.id AND re.winner=1),0) wins FROM teams t LEFT JOIN team_score_events s ON s.championship_id=t.championship_id AND s.team_id=t.id WHERE t.championship_id=? GROUP BY t.id,t.name ORDER BY 3 DESC,wins DESC,t.name LIMIT ?";List<TeamRankingEntry>x=new ArrayList<>();try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,id);p.setInt(2,limit);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new TeamRankingEntry(r.getString(1),r.getString(2),r.getInt(3),r.getInt(4)));}}return x;}
    @Override public void audit(String championshipId,String actor,String action,String details)throws SQLException{try(Connection c=database.connection()){audit(c,championshipId,actor,action,details);}}
    private void audit(Connection c,String championshipId,String actor,String action,String details)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(championship_id,actor,action,details,created_at) VALUES(?,?,?,?,?)")){p.setString(1,championshipId);p.setString(2,actor);p.setString(3,action);p.setString(4,details);p.setString(5,Instant.now().toString());p.executeUpdate();}}
    private ChampionshipDetails details(ResultSet r)throws SQLException{String sequence=r.getString("minigame_sequence");return new ChampionshipDetails(r.getString("id"),r.getString("name"),ChampionshipState.valueOf(r.getString("state")),ChampionshipMode.valueOf(r.getString("mode")),sequence.isBlank()?List.of():List.of(sequence.split(",")),r.getInt("current_round"),TieBreaker.valueOf(r.getString("tie_breaker")),r.getString("champion_id"),Instant.parse(r.getString("created_at")),parse(r.getString("completed_at")));}
    private Instant parse(String value){return value==null?null:Instant.parse(value);}
}
